<?php
namespace Tests\Feature;use App\Models\Company;use App\Models\Job;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class FeedbackMetricsAndApplicationCvTest extends TestCase{use RefreshDatabase;public function test_public_suggestion_is_received_and_admin_can_read_it():void{$this->postJson('/api/v1/suggestions',['email'=>'persona@example.com','category'=>'suggestion','message'=>'Me gustaría mejorar el buscador.'])->assertCreated();$admin=User::factory()->create(['is_admin'=>true]);$this->actingAs($admin,'sanctum')->getJson('/api/v1/admin/suggestions')->assertOk()->assertJsonPath('data.data.0.email','persona@example.com');}public function test_job_views_and_apply_starts_are_deduplicated_daily():void{$job=$this->job();foreach([1,2] as $_)$this->postJson("/api/v1/jobs/{$job->slug}/engagement",['event'=>'view','visitor_id'=>'visitor-one'])->assertCreated();$this->postJson("/api/v1/jobs/{$job->slug}/engagement",['event'=>'apply_start','visitor_id'=>'visitor-one'])->assertCreated();$this->assertDatabaseCount('job_engagement_events',2);}public function test_company_downloads_generated_cv_when_candidate_did_not_attach_file():void{$job=$this->job();$owner=User::factory()->create(['account_type'=>'company']);$job->company->members()->attach($owner->id,['role'=>'owner','status'=>'active']);$candidate=User::factory()->create(['account_type'=>'candidate']);$candidate->candidateProfile()->create(['professional_title'=>'Desarrolladora','summary'=>'Perfil profesional','skills'=>['PHP']]);$application=$this->actingAs($candidate,'sanctum')->postJson("/api/v1/candidate/jobs/{$job->slug}/applications",[])->assertCreated()->json('data.id');$response=$this->actingAs($owner,'sanctum')->get("/api/v1/company/applications/{$application}/document")->assertOk()->assertHeader('content-type','application/pdf');$this->assertStringStartsWith('%PDF',$response->getContent());}private function job():Job{$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active']);return Job::create(['company_id'=>$company->id,'slug'=>'developer','title'=>'Developer','summary'=>'Vacante','description'=>'Trabajo','requirements'=>[],'benefits'=>[],'location'=>'Santiago','modality'=>'Remoto','contract_type'=>'Tiempo completo','status'=>'active','published_at'=>now()]);}}
